if($customPage)$pageTitle=$customPage['title'];
?><!doctype html><html lang="<?=language()?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#ffffff"><meta name="csrf" content="<?=e($_SESSION['csrf'])?>"><title><?=e($pageTitle)?> · <?=e($siteName)?></title><script src="/assets/theme.js?v=3"></script><link rel="stylesheet" href="/assets/vendor/katex.min.css"><link rel="stylesheet" href="/assets/app.css?v=22"><?=languageData()?><script src="/assets/app.js?v=18" defer></script><script type="module" src="/assets/vendor/render.js"></script></head>
